<?php $exportQuery=http_build_query(array_filter($filters,fn($value)=>$value!==''&&$value!==0)); ?>
<div class="page-heading admin-heading"><div><span class="eyebrow">Admission operations</span><h1>Applications</h1><p>Paginated, filterable records across cycles, programmes, categories, eligibility and payments.</p></div><div class="heading-actions"><a class="button button-outline" href="<?= url('admin/applications/export'.($exportQuery?'?'.$exportQuery:'')) ?>">↓ Export filtered CSV</a></div></div>
<div class="filter-tabs"><a class="<?= $status===''?'active':'' ?>" href="<?= url('admin/applications') ?>">All <b><?= array_sum(array_column($counts,'total')) ?></b></a><?php foreach($counts as $count):?><a class="<?= $status===$count['status']?'active':'' ?>" href="<?= url('admin/applications?status='.rawurlencode($count['status'])) ?>"><?= e(ucwords(str_replace('_',' ',$count['status']))) ?> <b><?= e($count['total']) ?></b></a><?php endforeach?></div>
<section class="card application-table-card"><form class="table-filters admission-filter-grid" method="get" action="<?= url('admin/applications') ?>"><div class="search-field"><span>⌕</span><input name="q" value="<?= e($search) ?>" placeholder="Name, application number, email or mobile"></div><select name="status"><option value="">All statuses</option><?php foreach(['draft','submitted','resubmitted','eligibility_check','under_review','correction_required','approved','selected','payment_pending','fee_verified','admitted','rejected','withdrawn'] as $option):?><option value="<?= e($option) ?>"<?= selected($filters['status'],$option) ?>><?= e(ucwords(str_replace('_',' ',$option))) ?></option><?php endforeach?></select><select name="cycle"><option value="">All cycles</option><?php foreach($cycles as $cycle):?><option value="<?= e($cycle['id']) ?>"<?= selected($filters['cycle'],$cycle['id']) ?>><?= e($cycle['name']) ?></option><?php endforeach?></select><select name="program"><option value="">All programmes</option><?php foreach($programs as $program):?><option value="<?= e($program['id']) ?>"<?= selected($filters['program'],$program['id']) ?>><?= e($program['name'].' · '.$program['code']) ?></option><?php endforeach?></select><select name="category"><option value="">All categories</option><?php foreach($categories as $category):?><option value="<?= e($category['code']) ?>"<?= selected($filters['category'],$category['code']) ?>><?= e($category['name']) ?></option><?php endforeach?></select><select name="eligibility"><option value="">All eligibility results</option><?php foreach(['not_evaluated','eligible','needs_review','ineligible'] as $option):?><option value="<?= e($option) ?>"<?= selected($filters['eligibility'],$option) ?>><?= e(ucwords(str_replace('_',' ',$option))) ?></option><?php endforeach?></select><select name="payment"><option value="">All payment states</option><?php foreach(['pending','verified','rejected','refunded'] as $option):?><option value="<?= e($option) ?>"<?= selected($filters['payment'],$option) ?>><?= e(ucfirst($option)) ?></option><?php endforeach?></select><select name="reviewer"><option value="">All reviewers</option><?php foreach($reviewers as $reviewer):?><option value="<?= e($reviewer['id']) ?>"<?= selected($filters['reviewer'],$reviewer['id']) ?>><?= e($reviewer['name']) ?></option><?php endforeach?></select><button class="button button-primary button-sm">Apply filters</button><?php if($exportQuery):?><a href="<?= url('admin/applications') ?>">Clear</a><?php endif?></form><div class="table-wrap"><table class="application-table"><thead><tr><th>Applicant</th><th>Application</th><th>Cycle / programme</th><th>Category</th><th>Eligibility</th><th>Payment</th><th>Reviewer</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($applications as $application):?><tr><td><div class="person-cell"><span><?= e(strtoupper(substr($application['applicant_name'],0,1))) ?></span><div><b><?= e($application['applicant_name']) ?></b><small><?= e($application['email']) ?> · <?= e($application['mobile']) ?></small></div></div></td><td><b><?= e($application['application_number']?:'Draft') ?></b><small class="completion-small"><?= e($application['completion_percentage']) ?>% · <?= format_date($application['submitted_at']) ?></small></td><td><?= e($application['cycle_name']) ?><small class="completion-small"><?= e($application['selected_program_name']?:'No final allocation') ?></small></td><td><?= e($application['category']?:'—') ?></td><td><span class="status-pill status-<?= e($application['eligibility_status']) ?>"><?= e(ucwords(str_replace('_',' ',$application['eligibility_status']))) ?></span></td><td><?= $application['payment_status']?'<span class="status-pill status-'.e($application['payment_status']).'">'.e(ucfirst($application['payment_status'])).'</span>':'—' ?></td><td><?= e($application['reviewer_name']?:'Unassigned') ?></td><td><span class="status-pill status-<?= e($application['status']) ?>"><?= e(ucwords(str_replace('_',' ',$application['status']))) ?></span></td><td><a class="row-action" href="<?= url('admin/applications/'.$application['id']) ?>">→</a></td></tr><?php endforeach?></tbody></table><?php if(!$applications):?><div class="empty-inline">No applications match the current filters.</div><?php endif?></div><div class="table-footer"><span>Showing <?= count($applications) ?> of <?= number_format($total) ?> records</span><nav class="pagination"><?php if($page>1): $query=$_GET;$query['page']=$page-1;?><a href="?<?= e(http_build_query($query)) ?>">← Previous</a><?php endif?><b>Page <?= $page ?> of <?= $pages ?></b><?php if($page<$pages): $query=$_GET;$query['page']=$page+1;?><a href="?<?= e(http_build_query($query)) ?>">Next →</a><?php endif?></nav></div></section>
